//! Reader fixtures for positioned-model tests (`test-api`).
//!
//! Fixtures live in `context-read/tests/fixtures/v3` (authoritative manifest
//! `scenarios.json`, generated by the `ngrams` oracle); they are read from
//! disk so model and navigation tests need no dependency on `ngrams` or
//! `legacy`.

use std::{
    collections::BTreeMap,
    path::PathBuf,
};

use serde::Deserialize;

use super::{
    PositionedGraph,
    interchange::PositionedGraphSnapshot,
};
use crate::{
    BaseGraphKind,
    Token,
};

#[derive(Deserialize)]
struct Scenario {
    name: String,
}

/// Directory of the reader fixtures.
pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../context-read/tests/fixtures/v3")
}

fn read(path: PathBuf) -> Vec<u8> {
    std::fs::read(&path).unwrap_or_else(|error| panic!("{}: {error}", path.display()))
}

/// Every manifest fixture as `(name, snapshot)`, decoded and structurally
/// validated. Panics on any I/O, decoding or validation error.
pub fn fixture_snapshots() -> Vec<(String, PositionedGraphSnapshot)> {
    let scenarios: Vec<Scenario> =
        serde_json::from_slice(&read(fixtures_dir().join("scenarios.json"))).unwrap();
    assert!(!scenarios.is_empty());
    scenarios
        .into_iter()
        .map(|Scenario { name }| {
            let fixture: PositionedGraphSnapshot =
                serde_json::from_slice(&read(fixtures_dir().join(format!("{name}.json"))))
                    .unwrap_or_else(|error| panic!("{name}: {error}"));
            fixture
                .validate()
                .unwrap_or_else(|error| panic!("{name}: {error}"));
            (name, fixture)
        })
        .collect()
}

/// A reader fixture converted to a [`PositionedGraph`].
pub struct FixtureGraph {
    pub name: String,
    pub corpus: Vec<String>,
    pub graph: PositionedGraph<BaseGraphKind>,
    /// Fixture vertex key → token; the only way tests address vertices.
    pub names: BTreeMap<String, Token>,
}

/// Every manifest fixture, converted with
/// [`PositionedGraph::from_interchange_named`].
pub fn fixture_graphs() -> Vec<FixtureGraph> {
    fixture_snapshots()
        .into_iter()
        .map(|(name, fixture)| {
            let (graph, names) = PositionedGraph::from_interchange_named(&fixture.graph)
                .unwrap_or_else(|error| panic!("{name}: {error}"));
            FixtureGraph {
                name,
                corpus: fixture.corpus,
                graph,
                names,
            }
        })
        .collect()
}
